def resolve(path, cwd, links):
    # Validate cwd is canonical absolute path
    if not cwd.startswith('/'):
        return None

    # Parse path components
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split remaining into components
    components = remaining.split('/')

    link_count = 0

    while components:
        component = components.pop(0)

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
            continue

        # Append component to current path
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Parse the target
            if target.startswith('/'):
                current = '/'
                remaining_target = target[1:]
            else:
                # Target is relative to the directory containing the link
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                remaining_target = target

            # Prepend target components to remaining components
            target_components = remaining_target.split('/')
            components = target_components + components

    # Return result with no trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current

